"""Hand annotated anatomical landmarks in the generated reference canvases.
Coordinates are source pixels, not measurements inferred from prompt angles.
Each alternate mesh binds to its own pose on the same anatomical skeleton.
"""
S=.242424
POSES={}
def pose(name,origin,pts,head=0,staff=0,scale=S):
    keys='pelvis chest neck sr er gr sl el gl hr kr ar tr hl kl al tl cape1 cape2'.split()
    assert len(pts)==len(keys),(name,len(pts))
    POSES[name]=dict(origin=origin,scale=scale,points=dict(zip(keys,pts)),head=head,staff=staff)

